            "swapping_pxa_to_pxs_is_instant_the": "La conversion de PXA en PXS est instantanée : la moitié des PXA est convertie aussitôt, moins 5 % de frais, et l’autre moitié reste bloquée en garantie puis revient après ~3,5 jours, ajustée selon le prix à ce moment-là. La conversion de PXS en PXA est sans frais et se règle après ~3,5 jours, au prix médian des witnesses à l’échéance.",
