            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> peut transférer du Pixa Power directement vers un autre compte, en contournant le cycle habituel de power down de 13 semaines. Cette trésorerie est un compte multi-signature : aucune connexion seule ne peut donc déplacer ses fonds — utilisez <strong>Transfert groupé</strong> ci-dessous, où chaque détenteur de clé signe le même lot séparément avant qu’il soit fusionné et diffusé.",
