            "beware_of_spam_and_phishing_links_in": "Méfiez-vous des liens de spam et d’hameçonnage dans les mémos de transfert. N’ouvrez pas de liens provenant d’utilisateurs auxquels vous ne faites pas confiance. Ne communiquez jamais vos clés privées à des sites tiers. Les transactions n’apparaîtront qu’une fois confirmées sur la blockchain, ce qui peut prendre quelques minutes.",
