            "send_labels_are_assigned_in_the_classify": "Les libellés d’envoi sont attribués à l’étape Classer et mémorisés par compte. Modifiez-les en masse dans un tableur si vous préférez :",
            "say_what_each_outbound_send_was_so": "Indiquez ce qu’était chaque envoi sortant afin qu’il soit imposé correctement. Tout envoi est traité comme une vente imposable tant que vous ne le libellez pas — le marquer comme votre propre plateforme, vos propres portefeuilles, un don ou une donation change la fiscalité. Les libellés sont mémorisés pour la prochaine fois. Continuer les applique et recalcule le rapport.",
            "nothing_to_classify_no_outbound_transfers_to": "Rien à classer — aucun transfert sortant vers des tiers n’a été trouvé dans votre historique. Continuez pour vérifier et exporter.",
            "opening_balances_are_tokens_you_already_held": "Les soldes d’ouverture sont les jetons que vous déteniez déjà avant la première opération enregistrée de ce compte. Renseignez-les pour que les cessions anciennes aient un vrai prix de revient au lieu d’un gain à coût nul (surestimé). Le coût est le total payé pour ce montant d’ouverture, en {{cur}}.",
            "generate_a_record_of_your_on_chain": "Générez un relevé de votre activité en chaîne sur une période, classé fiscalement par le moteur FairFlow. Remplissez les options, classez vos envois, puis exportez en PDF, CSV ou JSON.",
            "values_use_the_wallets_current_price_a": "Les valeurs utilisent le prix {{fiat}} actuel du portefeuille — un instantané unique, sans historique. Le total des avoirs est donc exact, mais les plus-values réalisées sont approximatives (le produit et le prix de revient d’une cession partagent le même prix actuel). Branchez un oracle historique ou une source Kursliste pour des gains exacts.",
            "fiat_values_come_from_the_engines_pxs": "Les valeurs en monnaie fiduciaire proviennent du fournisseur de prix de démonstration référencé sur PXS du moteur ({{priceDataVersion}}) — branchez un véritable oracle ou une source Kursliste avant de vous fier aux chiffres.",
            "prefilled_from_the_chain_1_vest_pxa": "Prérempli depuis la chaîne : 1 VEST = {{_vestingRateAuto}} PXA, donc 1 000 000 VESTS = {{_vestingRateAuto_2}} PXP. VESTS × cette valeur = PXP, et 1 PXP vaut 1 PXA. Ne modifiez que pour remplacer.",
