            "csv_wealth_holdings_at_reference_date": "PATRIMOINE — avoirs à la date de référence",
            "csv_per_token_summary": "RÉSUMÉ PAR JETON",
            "csv_disposals_swaps": "CESSIONS ET ÉCHANGES",
