            "held_back_by_haircut": "Retenu par la décote",
            "when_you_settle_the_body_is_delivered": "Au règlement, le corps est livré en PXA au moment de l’exécution — un montant égal au poids impliqué par l’oracle multiplié par la décote. Voilà pourquoi « sous-jacent » est le mauvais mot : un sous-jacent suppose deux actifs distincts, une chose et un dérivé sur elle. Or le supra et l’atlas ne sont pas deux choses. Ils sont un seul corps vu en deux registres — le corps est ce qu’il est ; le supra est ce que l’esprit dit que ce corps devrait projeter. La conscience n’est pas quelque chose que le corps possède. Elle est le corps, éveillé.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "Aucun mécanisme monétaire ne supprime le risque. Un jeton à réserve fiduciaire le concentre dans l’intégrité de cette réserve et la solvabilité d’un émetteur. Le supra déplace ce risque vers la volatilité de l’économie créative — la variance de l’Atlas — et vers l’intégrité du consensus — la solidité de la boussole des witnesses — puis le gère au grand jour par la surcollatéralisation et une décote qui ne défend rien, plutôt que de le déguiser derrière un nombre défendu.",
