            "you_are_about_to_request_a_change": "Vous êtes sur le point de demander un changement de compte de récupération pour <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Désignez un compte de confiance — une personne cofondatrice, un portefeuille jumeau que vous contrôlez, ou un contact que vous pouvez joindre par un autre canal — pour vous aider à retrouver l’accès si votre clé owner venait à être perdue ou compromise. La procédure de récupération s’appuie sur l’historique de votre clé owner : à lui seul, le compte de récupération ne peut donc jamais s’emparer de votre compte, il ne peut que vous aider à le récupérer. Les changements prennent effet après un délai de 30 jours.",
            "strong_30_day_waiting_period_strong_changing": "<strong>Délai de 30 jours.</strong> Le changement de compte de récupération n’est pas immédiat. Une nouvelle demande prend effet <strong>30 jours après diffusion</strong> ; jusque-là, le compte de récupération actuel reste en vigueur. Une nouvelle diffusion pendant le délai remplace la demande en attente. Redéfinir la valeur actuelle annule un changement en attente.",
            "pick_someone_you_trust_personally_a_co": "Choisissez une personne en qui vous avez personnellement confiance : une cofondatrice, un compte jumeau que vous contrôlez, ou un portefeuille dont vous pouvez joindre le propriétaire autrement.",
            "generate_a_fresh_seed_phrase_to_derive": "Générez une nouvelle phrase mnémonique pour dériver de nouvelles clés pour votre compte. Votre phrase mnémonique est la clé maîtresse de toutes vos clés — conservez-la en lieu sûr et ne la partagez jamais. La clé owner servira à signer la transaction de mise à jour lorsque vous confirmerez ci-dessous.",
            "this_will_strong_cancel_any_pending_recovery": "Cela <strong>annulera tout changement de compte de récupération en attente</strong> en rediffusant la même valeur que votre compte de récupération actuel. La demande de 30 jours sera remplacée ; le compte de récupération actuel reste en vigueur pendant toute la durée.",
            "once_broadcast_the_chain_will_create_a": "Une fois diffusée, la chaîne créera une demande en attente qui prendra effet dans <strong>30 jours</strong>. Votre compte de récupération actuel (<0>@{{currentRecovery}}</0>) reste en vigueur jusque-là. Votre <strong>clé owner</strong> vous sera demandée.",
            "posting_description_1": "Cette clé doit être utilisée pour les actions sociales, comme publier, commenter et voter. Elle dispose d’un ensemble limité de permissions et ne peut pas servir aux actions monétaires.",
            "posting_description_2": "Utilisez cette clé pour vous connecter aux réseaux sociaux basés sur Pixa comme Pixagram.com. Conservez-la en lieu sûr.",
            "active_description_1": "Cette clé dispose de permissions supplémentaires pour les actions monétaires plus sensibles, comme transférer et échanger des jetons.",
            "active_description_2": "Lors d’une action liée au portefeuille, il peut vous être demandé de vous authentifier avec votre clé Active. Ne saisissez votre Active Key que dans des applications de confiance, car quiconque a accès à cette clé peut prendre vos jetons.",
            "owner_description_1": "La clé Owner est requise pour modifier les autres clés. Elle dispose de permissions supplémentaires pour récupérer votre compte ou changer vos autres clés. C’est la clé la plus importante ; conservez-la en sécurité hors ligne.",
