            "for_conquest_is_never_accomplished_no_milestone": " car la conquête n’est jamais achevée. Aucun jalon n’est un sommet ; l’œuvre n’est jamais finie.",
            "lift_the_smallest_accounts_as_you_climb": " Élève les plus petits comptes à mesure que tu montes, car le fretin d’aujourd’hui est le maître de demain.",
            "but_treat_it_sometimes_as_an_impostor": " mais traite-la parfois en imposteur — et sois toujours juste. Ce que la foule aime n’est pas toujours ce qu’il y a de meilleur ; reste ton propre juge.",
            "to_dislike_is_your_right_and_to": " Ne pas aimer est ton droit, et juger n’est pas censurer ; vote négativement ou passe ton chemin devant toute œuvre qui ne te touche pas.",
