            "contribute_to_it_not_for_today_or": " Contribue-y non pour aujourd’hui ni pour hier, mais pour toujours.",
            "it_funds_development_and_the_protocol_the": " — il finance le développement et le protocole. La promotion de Pixa appartient à ses membres, jamais à sa trésorerie.",
