            "these_principles_are_the_foundation_of_pixa": "Ces principes sont le fondement de Pixa et de la communauté que nous bâtissons sur elle — honnête, juste, durable et unie. Le protocole n’interdit que ce qu’il doit ; tout ce qui est bon au-delà de cette ligne relève du caractère que nous choisissons. Voici ce caractère : l’esprit dans lequel nous créons, la manière dont nous nous traitons les uns les autres et l’exigence que nous nous imposons. Ils ne lient personne par la force, et pourtant ils nous lient tous.",
