            "this_nft_license_agreement_the_agreement": "Le présent Contrat de licence NFT (le « Contrat ») définit les conditions personnalisables selon lesquelles le créateur (ci-après dénommé l’« Auteur ») accorde certains droits à l’acquéreur (le « Détenteur ») de jetons non fongibles (NFT) associés à une collection déterminée d’œuvres numériques (la « Collection »). Le présent Contrat a pour objet d’offrir un cadre de licence souple, transparent et équitable, capable de s’adapter à différents cas d’usage, modèles économiques et intentions artistiques, tout en garantissant que les droits moraux de l’Auteur demeurent intacts et pleinement préservés. Cette structure est spécialement conçue pour les créateurs de NFT qui souhaitent accorder des droits d’usage sur mesure aux détenteurs de leurs actifs numériques, permettant un éventail d’interactions avec l’œuvre et d’exploitations de celle-ci selon les préférences retenues par l’Auteur.",
            "ownership_and_moral_rights": "Propriété et droits moraux",
            "the_author_is_and_shall_remain_the_sole": "L’Auteur est et demeure le seul et exclusif titulaire de l’ensemble des droits de propriété intellectuelle sur les œuvres sous-jacentes et sur tout contenu associé lié aux NFT. L’Auteur conserve l’ensemble de ses droits moraux, y compris le droit d’être identifié comme créateur et de s’opposer à toute déformation, mutilation ou autre modification de l’œuvre qui porterait atteinte à son honneur ou à sa réputation. Ces droits moraux sont incessibles et perpétuels, et doivent être respectés par tous les Détenteurs et par les tiers. Le présent Contrat ne saurait être interprété comme une renonciation à ces droits ou comme une limitation de ceux-ci.",
