            "the_holder_of_an_nft_is_granted_a_non": "Le Détenteur d’un NFT se voit accorder une licence non exclusive, mondiale et libre de redevances pour utiliser l’œuvre numérique associée au NFT, mais uniquement dans la mesure expressément autorisée par l’Auteur ci-dessous. La licence est strictement liée au NFT spécifique détenu et est automatiquement transférée en cas de revente. La présente section a pour objet de permettre à l’Auteur de choisir l’étendue des droits accordés à chaque Détenteur, offrant ainsi clarté juridique et souplesse créative aux deux parties. Pour chaque droit énuméré, l’Auteur peut indiquer si le Détenteur est autorisé à l’exercer.",
